package com.morongaming.forsakenrealm;
import android.app.*;import android.os.Build;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.widget.Toast;import java.io.*;import java.net.*;import java.security.MessageDigest;import java.util.Locale;import java.util.concurrent.*;import org.json.JSONObject;
final class AppUpdates {
 private static final String MANIFEST="https://raw.githubusercontent.com/joesiebert79-sudo/forsaken-realm-server/main/app-release.json";
 private final Activity host;private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean checked,busy;private int pendingVersion;
 AppUpdates(Activity host){this.host=host;}
 private long installed()throws Exception{return host.getPackageManager().getPackageInfo(host.getPackageName(),0).versionCode;}
 void check(){if(checked)return;checked=true;worker.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(MANIFEST).openConnection();c.setConnectTimeout(4000);c.setReadTimeout(4000);c.setRequestProperty("Cache-Control","no-cache");JSONObject info;try(InputStream in=c.getInputStream()){info=new JSONObject(new String(read(in,16384),"UTF-8"));}finally{c.disconnect();}if(info.optLong("versionCode")<=installed())return;URL url=new URL(info.getString("apkUrl"));if(!"https".equals(url.getProtocol())||!"github.com".equals(url.getHost())||!url.getPath().startsWith("/joesiebert79-sudo/forsaken-realm-server/releases/download/"))return;String hash=info.getString("apkSha256");if(!hash.matches("[a-fA-F0-9]{64}"))return;host.runOnUiThread(()->{if(host.isFinishing()||host.isDestroyed())return;new AlertDialog.Builder(host).setTitle("Forsaken Realm update").setMessage("A new app update is ready. Download and install it now?").setPositiveButton("Update",(d,w)->download(info)).setNegativeButton("Later",null).show();});}catch(Exception ignored){}});}
 private static byte[] read(InputStream in,int limit)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>limit)throw new IOException("Download too large");}return out.toByteArray();}
 private void download(JSONObject info){if(busy)return;busy=true;Toast.makeText(host,"Downloading update…",Toast.LENGTH_LONG).show();worker.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(info.getString("apkUrl")).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(20000);File part=new File(host.getCacheDir(),"apk-update.part");MessageDigest digest=MessageDigest.getInstance("SHA-256");long size=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(part)){byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1){size+=n;if(size>160L*1024*1024)throw new IOException("Update too large");digest.update(bytes,0,n);out.write(bytes,0,n);}}finally{c.disconnect();}StringBuilder actual=new StringBuilder();for(byte b:digest.digest())actual.append(String.format(Locale.ROOT,"%02x",b&255));if(!actual.toString().equalsIgnoreCase(info.getString("apkSha256")))throw new IOException("Update could not be verified");File target=new File(host.getCacheDir(),"apk-update.apk");if(target.exists()&&!target.delete())throw new IOException("Cannot replace update");if(!part.renameTo(target))throw new IOException("Cannot prepare update");pendingVersion=info.getInt("versionCode");host.runOnUiThread(()->install());}catch(Exception e){host.runOnUiThread(()->Toast.makeText(host,"Update download failed. Try again next time you open the app.",Toast.LENGTH_LONG).show());checked=false;}finally{busy=false;}});}
 void resume(){if(pendingVersion>0&&new File(host.getCacheDir(),"apk-update.apk").isFile()&&(Build.VERSION.SDK_INT<26||host.getPackageManager().canRequestPackageInstalls()))install();}
 private void install(){try{if(pendingVersion<=installed()){pendingVersion=0;return;}if(Build.VERSION.SDK_INT>=26&&!host.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(host).setTitle("Allow app updates").setMessage("Android needs your permission to install updates from Forsaken Realm. Your game progress stays on your server.").setPositiveButton("Open Android settings",(d,w)->host.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+host.getPackageName())))).setNegativeButton("Later",null).show();return;}Intent install=new Intent(Intent.ACTION_VIEW);install.setDataAndType(Uri.parse("content://"+host.getPackageName()+".updates/update.apk"),"application/vnd.android.package-archive");install.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);host.startActivity(install);}catch(Exception e){Toast.makeText(host,"Android could not open the installer",Toast.LENGTH_LONG).show();}}
 void close(){worker.shutdownNow();}
}
